int read_tfra_box(MOVContext *mov, AVIOContext *f) {
    uint32_t box_type;
    int64_t box_size;
    int version, track_id, field_length, item_count;
    MOVFragmentIndex *index;
    int i;

    box_size = avio_rb32(f);
    box_type = avio_rl32(f);

    if (box_type != MKTAG('t', 'f', 'r', 'a')) {
        avio_seek(f, box_size - 8, SEEK_CUR);
        return AVERROR_INVALIDDATA;
    }

    version = avio_r8(f);
    track_id = avio_rb16(f);
    field_length = avio_r8(f);
    item_count = avio_rb32(f);

    index = av_malloc(sizeof(*index));
    if (!index)
        return AVERROR(ENOMEM);

    index->track_id = track_id;
    index->item_count = item_count;
    index->entries = av_malloc_array(item_count, sizeof(*index->entries));
    if (!index->entries) {
        av_free(index);
        return AVERROR(ENOMEM);
    }

    for (i = 0; i < item_count; i++) {
        if (version < 1) {
            index->entries[i].time = 0;
            index->entries[i].offset = avio_rb32(f);
        } else {
            index->entries[i].time = avio_rb32(f);
            index->entries[i].offset = avio_rb64(f);
        }
    }

    avio_seek(f, box_size - 8, SEEK_CUR);
    mov->fragment_index = index;
    return 0;
}

int read_tfra_box(MOVContext *mov, AVIOContext *f) {
    uint32_t box_type;
    uint64_t box_size;
    int64_t box_start;

    box_type = avio_rl32(f);
    if (box_type != MKTAG('t', 'f', 'r', 'a')) {
        avio_seek(f, -4, SEEK_CUR);
        return AVERROR_INVALIDDATA;
    }

    box_size = avio_rl64(f);
    box_start = avio_tell(f);

    if (mov->fragment_index) {
        av_free(mov->fragment_index);
    }

    mov->fragment_index = av_mallocz(sizeof(MOVFragmentIndex));
    if (!mov->fragment_index) {
        return AVERROR(ENOMEM);
    }

    mov->fragment_index->version = avio_r8(f);
    mov->fragment_index->track_id = avio_rl32(f);
    mov->fragment_index->field_length = avio_r8(f);
    mov->fragment_index->item_count = avio_rl32(f);

    if (mov->fragment_index->item_count > 1024) {
        av_free(mov->fragment_index);
        return AVERROR_INVALIDDATA;
    }

    for (int i = 0; i < mov->fragment_index->item_count; i++) {
        mov->fragment_index->items[i].time = avio_rl32(f);
        mov->fragment_index->items[i].offset = avio_rl32(f);
    }

    avio_seek(f, box_start + box_size, SEEK_SET);

    return 0;
}

int read_tfra_box(MOVContext *mov, AVIOContext *f) {
    uint32_t box_type;
    int version;
    uint32_t track_id;
    uint16_t field_length;
    uint32_t item_count;
    uint64_t box_size;
    int ret = 0;

    if (avio_r8(f) != 't' || avio_r8(f) != 'f' || avio_r8(f) != 'r' || avio_r8(f) != 'a') {
        av_log(NULL, AV_LOG_ERROR, "Invalid box type, expected 'tfra'\n");
        return AVERROR_INVALIDDATA;
    }

    box_size = avio_rb32(f);

    version = avio_r8(f);
    track_id = avio_rb24(f);
    field_length = avio_rb16(f);
    item_count = avio_rb32(f);

    if (field_length != 32) {
        av_log(NULL, AV_LOG_ERROR, "Unsupported field length: %d\n", field_length);
        return AVERROR_INVALIDDATA;
    }

    mov->fragment_index = av_mallocz(sizeof(MOVFragmentIndex));
    if (!mov->fragment_index)
        return AVERROR(ENOMEM);

    mov->fragment_index->version = version;
    mov->fragment_index->track_id = track_id;
    mov->fragment_index->item_count = item_count;

    for (uint32_t i = 0; i < item_count; i++) {
        uint64_t time, offset;

        if (version == 0) {
            time = avio_rb32(f);
            offset = avio_rb32(f);
        } else {
            time = avio_rb64(f);
            offset = avio_rb64(f);
        }

        if (!mov->fragment_index->items) {
            mov->fragment_index->items = av_mallocz(sizeof(MOVFragmentItem));
        } else {
            mov->fragment_index->items = av_realloc(mov->fragment_index->items,
                                                    (i + 1) * sizeof(MOVFragmentItem));
        }

        if (!mov->fragment_index->items) {
            av_log(NULL, AV_LOG_ERROR, "Memory allocation failed for fragment items\n");
            return AVERROR(ENOMEM);
        }

        mov->fragment_index->items[i].time = time;
        mov->fragment_index->items[i].offset = offset;
    }

    if (avio_seek(f, box_size, SEEK_SET) < 0) {
        av_log(NULL, AV_LOG_ERROR, "Failed to seek to the end of the 'tfra' box\n");
        return AVERROR(EIO);
    }

    return ret;
}

int mov_read_tfra(MOVContext *mov, AVIOContext *f) {
    int version;
    int track_id;
    int field_length;
    int item_count;
    int i;
    int ret;
    int64_t size;
    int64_t end_pos;
    MOVTFRACtx *tfra;
    MOVFragmentIndex *fi;

    if (avio_rl32(f) != MKTAG('t', 'f', 'r', 'a'))
        return AVERROR_INVALIDDATA;
    avio_skip(f, 4); // skip data size

    version = avio_r8(f);
    track_id = avio_rb16(f);
    field_length = avio_r8(f);
    item_count = avio_rb32(f);

    if (field_length != 8)
        return AVERROR_PATCHWELCOME;

    fi = av_mallocz(sizeof(*fi));
    if (!fi)
        return AVERROR(ENOMEM);

    fi->track_id = track_id;
    fi->time_offset_count = item_count;
    fi->time_offset = av_malloc_array(item_count, sizeof(*fi->time_offset));
    if (!fi->time_offset) {
        av_freep(&fi);
        return AVERROR(ENOMEM);
    }

    for (i = 0; i < item_count; i++) {
        if (version == 0) {
            fi->time_offset[i] = avio_rb64(f);
        } else if (version == 1) {
            fi->time_offset[i] = (uint64_t)avio_rb32(f) << 32 | avio_rb32(f);
        } else {
            av_freep(&fi->time_offset);
            av_freep(&fi);
            return AVERROR_PATCHWELCOME;
        }
    }

    end_pos = avio_tell(f);
    size = avio_size(f);
    if (end_pos > size) {
        av_freep(&fi->time_offset);
        av_freep(&fi);
        return AVERROR_INVALIDDATA;
    }

    mov->fragment_index = fi;
    return 0;
}

